  font-size: clamp(0.7rem, 1.2vw, 0.9rem);
  background: var(--slide-code-bg);
  border: 1px solid var(--slide-border);
  padding: 1.2rem 1.5rem;
  border-radius: 10px;
  overflow: auto;
  max-height: 64vh;
  line-height: 1.5;
}
.slide :not(pre) > code {
  background: rgba(127, 127, 127, 0.18);
  color: var(--slide-fg);
  padding: 0.1em 0.4em;
  border-radius: 4px;
  font-size: 0.9em;
}
/* Dense code slides: shrink code so left/right columns fit without scroll. */
.slide .cols pre {
  font-size: clamp(0.6rem, 1vw, 0.78rem);
  line-height: 1.4;
}
.copy-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 0.25em 0.7em;
  font: inherit;
  font-size: 0.75rem;
  line-height: 1.4;
  color: #ddd;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}
.slide pre:hover .copy-btn,
.copy-btn:focus-visible {
  opacity: 1;
}
.copy-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}
.copy-btn.copied {
  color: #fff;
  background: var(--slide-accent);
  border-color: var(--slide-accent);
  opacity: 1;
}
#progress {
  position: fixed;
  bottom: 0;
  left: 0;
  height: 4px;
  width: 0;
  background: var(--slide-accent);
  transition: width 0.2s ease;
  z-index: 10;
}
#counter {
  position: fixed;
  bottom: 12px;
  right: 18px;
  font-size: 0.9rem;
  color: var(--slide-muted);
  font-variant-numeric: tabular-nums;
  z-index: 10;
}
#hint {
  position: fixed;
  bottom: 12px;
  left: 18px;
  font-size: 0.8rem;
  color: var(--slide-muted);
  opacity: 0.6;
  z-index: 10;
}

